//! Fixed data for build 104319 that can't be read from the install at run
//! time. It is embedded in the binary. Where each file comes from, and why
//! it is kept, is recorded in `docs/dev/data-sources.md`.

#![forbid(unsafe_code)]

/// What the client reads for each statescript state class in a frame: our
/// description of its reader code, generated by
/// `research/ida/extract_statescript_codecs.py` from a memory image (the
/// program's code is encrypted on disk, so the server can't read it there).
pub const STATESCRIPT_CODECS: &str = include_str!("../data/statescript_codecs.json");

/// Research names for the statescript graphs (`lucy script query`): class
/// aliases, the STU fields that hold a variable, logical buttons, the hero
/// select and HUD graphs, each game mode's scripts and the variable names the
/// server uses.
pub const STATESCRIPT_NAMES: &str = include_str!("../data/statescript_names.json");
